-- King's Running AI Analytics - Health Data Migration
-- Run as postgres role in Supabase SQL Editor

VALUES ('0b308f84-1dea-4277-bd59-91b4bb229f1c', 'HKD', 'dark', 'user')
ON CONFLICT DO NOTHING;

DO $$
DECLARE v_user_id INTEGER;
BEGIN
  SELECT id INTO v_user_id FROM users WHERE "openId" = '0b308f84-1dea-4277-bd59-91b4bb229f1c' LIMIT 1;
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'User not found!';
  END IF;




END $$;

SELECT 'users' as tbl, COUNT(*) as cnt FROM users
UNION ALL SELECT 'body_composition', COUNT(*) FROM body_composition
UNION ALL SELECT 'heart_rate_logs', COUNT(*) FROM heart_rate_logs
UNION ALL SELECT 'sleep_logs', COUNT(*) FROM sleep_logs;